card.contractYaml:
id: "01"
name: hfc_districts   # table: hfc_districts
owner: ran-avak
steward: data-engineering-team-lead
custodian: information-factory-team
network: public
pipeline: db-oref-base > ingestion_db > portal_api
source: { system: db-oref-base, layer: hfc_districts, format: PostGIS }
refresh: daily
retention: latest_version_plus_boundary_history
columns:
  - { name: muni_id, type: int, nullable: false }
  - { name: name_he, type: varchar(100), nullable: false }
  - { name: muni_type, type: varchar(30), nullable: false }
  - { name: district_id, type: int, nullable: false }
  - { name: subdistrict_id, type: int, nullable: true }
  - { name: updated_at, type: timestamp, nullable: false }
  - { name: area_km2, type: float, nullable: false }
  - { name: centroid_lat, type: float, nullable: false }
  - { name: centroid_lon, type: float, nullable: false }
  - { name: geom_valid, type: boolean, nullable: false }
  - { name: geom, type: geometry(MultiPolygon,4326), nullable: false }
validation:
  unique: primary key per layer (duplicate fails the load)
  invalid_geometry: record rejected
  orphan_hierarchy_key: load rejected
support_sla:
  hours: Sun-Thu 09:00-18:00
  first_response: { routine: 1 business day, emergency: 3 hours }
